actions.script:
def zinr = context.zinr
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
periodStr = fromD + ' to ' + thruD
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def ef = ec.entity.find("zenith.erp.pos.PosTransactionView").condition("statusId","PtVoided")
    .condition("entryDate","greater-equals",ds).condition("entryDate","less-equals",de).orderBy("-entryDate").limit(2000)
if (_org && _org != '_NA_') ef.condition("organizationPartyId", _org)
def all = ef.list()
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) all = all.findAll { ((it.transactionNumber ?: '').toLowerCase().contains(stx)) }
def num = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def dt = { v -> v == null ? '' : ec.l10n.format(v, 'dd-MM-yyyy HH:mm') }
def x = { v -> (v ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
rows = all.collect { r ->
    [no:x(r.transactionNumber ?: r.transactionId), date:dt(r.entryDate), term:x(r.terminalName),
     sub:num(r.subtotal), disc:num(r.discountTotal), amt:num(r.payableAmount)] }
rowCountStr = all.size().toString()
totalStr = num(all.inject(0.0G) { a, it -> a + ((it.payableAmount ?: 0) as BigDecimal) })
